import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:21.5px;line-height:1.3}.box h2{font-size:27px;margin-bottom:5px}.tbl{font-size:19.5px}.note,.warn{font-size:18px}.tbl th,.tbl td{padding:3px 6px}.iq ol{font-size:20.5px;line-height:1.3}.pill{font-size:17px}.grid{gap:13px}.handle{bottom:-12px}.box{padding:11px 13px}.tagline{font-size:20px;margin-bottom:10px}</style>
<div class="title">📢 HxGN EAM Bulletins <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Push important messages to users inside EAM, force acknowledgement for critical ones, and track who read them. (HxGN EAM Bulletins brief, 12.1.1)</div>
<div class="grid">
<div class="box c1"><h2>1. What is a bulletin?</h2><ul><li>A message users must <b>see and acknowledge</b></li><li>Planned upgrades, emergency maintenance notices, system updates</li><li>Admin creates it, picks recipients, tracks who acknowledged</li></ul></div>
<div class="box c2"><h2>2. Bulletin Setup (record)</h2><ul><li>Description, <b>Status</b>, <b>Start / End Date</b>, <b>Critical</b></li><li>User Defined Fields for admin tracking</li><li>Tabs: <b>Message</b>, <b>Recipients</b>, <b>Acknowledged</b></li></ul></div>
<div class="box c3"><h2>3. Status rules</h2><table class="tbl"><tr><th>Status</th><th>Edit?</th></tr><tr><td><b>Inactive</b></td><td>Record + tabs editable</td></tr><tr><td><b>Active</b></td><td>Locked (set back to Inactive to edit)</td></tr><tr><td><b>Expired</b> ✔</td><td>System sets it after End Date; no more edits</td></tr></table><div class="note">Only Inactive / Active. No customer-defined statuses.</div></div>
<div class="box c4"><h2>4. Before you can Activate</h2><ul><li>At least <b>1 message</b> in the Default Language (<b>DEFLANG</b>)</li><li>At least <b>1 recipient</b> on Recipients tab</li></ul><div class="warn">Miss either one and Active is blocked.</div></div>
<div class="box c5"><h2>5. Message tab</h2><ul><li><b>One message per language</b></li><li>Plain text or <b>HTML</b> (images, links, colors)</li><li>HTML needs install parameter <b>HTMLCOMM = ON</b></li></ul></div>
<div class="box c6"><h2>6. Recipients tab</h2><ul><li>Add by <b>User</b> or by <b>User Group</b> (both allowed)</li><li>Each user / group becomes its own record</li></ul></div>
<div class="box c7"><h2>7. BULLOGIN install parameter</h2><table class="tbl"><tr><th>Value</th><th>On login</th></tr><tr><td><b>ALL</b></td><td>Pop-up if any bulletin to review</td></tr><tr><td><b>CRIT</b></td><td>Pop-up only for Critical ones</td></tr><tr><td><b>NONE</b></td><td>No pop-up, icon still shown</td></tr><tr><td><b>OFF</b> (default)</td><td>Feature disabled, no icon</td></tr></table></div>
<div class="box c8"><h2>8. User side</h2><ul><li><b>Bulletin Notification icon</b> (header, top right) with a count</li><li><b>Bulletin Display</b> pop-up: Critical can't be closed until <b>Acknowledge</b></li><li>Acknowledged tab logs user, date, language</li><li><b>Bulletin History</b> screen = my acknowledged bulletins</li></ul></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">9a. Bulletin flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Bulletin Setup (Inactive)</span><span class="arr">→</span><span class="pill">Message + Recipients</span><span class="arr">→</span><span class="pill">Active</span><span class="arr">→</span><span class="pill">Acknowledge</span><span class="arr">→</span><span class="pill">Expired</span></div></div>
<div class="box iq"><h2>9b. Consultant tips</h2><ol><li>BULLOGIN is OFF by default: switch it on first</li><li>Editing a message deletes its old acknowledgements</li><li>Use Critical only for must-read notices</li><li>Web browser only in 12.1.1 (not mobile apps)</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">9c. Key points</h2><ul><li>DEFLANG msg + 1 recipient</li><li>Active = locked</li><li>CRIT = login pop-up</li></ul></div>
</div></div>'''
build("/workspace/social/posts/2026-10-22-linkedin-eam-bulletins",B,1350,"Rahul Kumar")
